const $=id=>document.getElementById(id),fmt=n=>Number.isFinite(n)?n.toLocaleString('zh-TW',{maximumFractionDigits:2}):'—',pct=n=>Number.isFinite(n)?fmt(n)+'%':'—';let mode='示範';let state={cash:80,other:150,debtOther:0,pools:[{name:'中信｜融資帳戶',type:'融資',value:300,fixed:0,debt:180,trigger:130,target:166},{name:'凱基｜質押帳戶',type:'質押',value:400,fixed:0,debt:220,trigger:130,target:166}]};const demo=JSON.parse(JSON.stringify(state));
let active=0;const familyDemo=[{name:'媽媽',data:demo},{name:'小孩 A',data:{cash:20,other:80,debtOther:0,pools:[{name:'中信｜融資帳戶',type:'融資',value:150,fixed:0,debt:100,trigger:130,target:166}]}},{name:'小孩 B',data:{cash:30,other:100,debtOther:0,pools:[{name:'凱基｜質押帳戶',type:'質押',value:200,fixed:0,debt:90,trigger:130,target:166}]}}];let family=JSON.parse(JSON.stringify(familyDemo));state=family[0].data;
$('date').value=new Date().toLocaleDateString('en-CA');
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function mark(){mode='使用者輸入';$('mode').textContent='目前為使用者輸入；請核對手機帳戶資料與借款契約。金額單位：萬元。';}
function inputs(){family[active].data=state;$('member').innerHTML=family.map((m,i)=>`<option value="${i}" ${i===active?'selected':''}>${esc(m.name||'未命名成員')}</option>`).join('');$('memberName').value=family[active].name;for(const key of ['cash','other','debtOther'])$(key).value=state[key];$('pools').innerHTML=state.pools.map((p,i)=>`<article class="pool"><div class="poolhead"><label>券商／銀行與帳戶名稱<input data-i="${i}" data-key="name" value="${esc(p.name)}"></label><label>借款種類<select data-i="${i}" data-key="type"><option ${p.type==='融資'?'selected':''}>融資</option><option ${p.type==='質押'?'selected':''}>質押</option></select></label><button data-remove="${i}" aria-label="刪除${esc(p.name)}">刪除</button></div><div class="fields">${[['value','擔保股票市值'],['fixed','固定擔保計值'],['debt','借款本金'],['trigger','追繳門檻 %'],['target','回復目標 %']].map(([key,label])=>`<label>${label}<input type="number" min="0" step="0.01" data-i="${i}" data-key="${key}" value="${p[key]}"></label>`).join('')}</div><div id="result${i}" class="status"></div></article>`).join('');render();}
function render(){family[active].data=state;try{family.forEach(m=>RiskEngine.validate(m.data));$('error').textContent='';}catch(e){$('error').textContent=e.message;$('summary').innerHTML='<div class="notice danger">輸入不完整，暫停計算。</div>';$('stress').textContent='請先修正輸入';$('scenarios').innerHTML='';$('chart').innerHTML='';$('overview').innerHTML='';$('comparison').innerHTML='';state.pools.forEach((p,i)=>{if($('result'+i))$('result'+i).textContent='請先修正輸入';});return;}
 const now=RiskEngine.calculate(state),drop=Number($('drop').value)/100,r=RiskEngine.calculate(state,drop);$('dropLabel').textContent=pct(drop*100);renderOverview(drop);
 const buffers=now.pools.filter(p=>p.debt>0).map(p=>p.value>0?Math.max(0,p.buffer*100):p.breach?0:Infinity);const min=buffers.length?Math.min(...buffers):null;
 $('summary').innerHTML=[['投資淨資產',fmt(now.equity)+' 萬','股票＋現金－投資借款'],['股票曝險倍數',now.leverage===null?'淨資產非正':fmt(now.leverage)+' 倍','股價跌幅會放大淨資產損失'],['債務／投資資產',pct(now.ltv),'總借款 '+fmt(now.debt)+' 萬'],['最短追繳距離',min===Infinity?'無股票跌幅觸發':pct(min),'依各帳戶門檻獨立估算']].map(([label,value,hint])=>`<div class="metric"><span>${label}</span><strong>${value}</strong><small>${hint}</small></div>`).join('');
 now.pools.forEach((p,i)=>{const el=$('result'+i);let buffer=p.value>0?pct(Math.max(0,p.buffer*100)):p.breach?'0%':'無股票跌幅觸發';el.className='status '+(p.breach?'danger':p.debt>0&&p.value>0&&p.buffer<.2?'warning':'');el.innerHTML=`維持率 <b>${p.ratio===null?'無借款':pct(p.ratio)}</b> · 距追繳可跌 <b>${p.debt>0?buffer:'—'}</b><br>${p.breach?'已低於追繳門檻，請立即確認通知與补款期限。':p.debt===0?'此帳戶無借款。':'目前未低於門檻；不代表已取消既有追繳紀錄。'}<br>跌 ${pct(drop*100)} 後：${p.ratio===null?'無借款':pct(r.pools[i].ratio)}${r.pools[i].breach?'，低於門檻':'，未低於門檻'}`;});
 $('stress').innerHTML=`<div class="status ${r.breached?'danger':r.equity<=0?'danger':' '}" role="status">${r.breached?`${r.breached} 個帳戶低於追繳門檻`:'各帳戶未低於追繳門檻'}${r.equity<=0?'；投資淨資產非正':''}</div>`+[['壓力後淨資產',fmt(r.equity)+' 萬'],['淨資產損失',now.equity>0?pct((now.equity-r.equity)/now.equity*100):'基期非正'],['需追繳帳戶：償還本金至目標',fmt(r.repay)+' 萬'],['或新增合格擔保計值至目標',fmt(r.add)+' 萬'],['可動用現金',fmt(state.cash)+' 萬'],['本金還款方案現金缺口',fmt(r.cashGap)+' 萬']].map(([a,b])=>`<div class="stressline"><span>${a}</span><strong>${b}</strong></div>`).join('');
 $('scenarios').innerHTML=[0,.1,.2,.3,.4,.5].map(d=>{const t=RiskEngine.calculate(state,d);return `<tr class="${t.breached?'danger':''}"><td>${pct(d*100)}</td><td>${fmt(t.equity)} 萬</td><td>${t.breached}</td><td>${fmt(t.repay)} 萬</td><td>${fmt(t.cashGap)} 萬</td></tr>`;}).join('');
 const points=Array.from({length:61},(_,i)=>RiskEngine.calculate(state,i/100).equity),lo=Math.min(0,...points),hi=Math.max(1,...points),y=v=>150-(v-lo)/(hi-lo)*125;const line=points.map((v,i)=>(i?'L':'M')+(35+i*5)+','+y(v)).join(' ');$('chart').innerHTML=`<text x="35" y="14" font-size="12" fill="#647b92">投資淨資產（萬元）</text><line x1="35" x2="335" y1="${y(0)}" y2="${y(0)}" stroke="#9aacbf" stroke-dasharray="4"/><path d="${line}" fill="none" stroke="#139c92" stroke-width="3"/><circle cx="${35+drop*500}" cy="${y(r.equity)}" r="5" fill="#182d48"/><text x="0" y="${y(points[0])+4}" font-size="11">${Math.round(points[0])}</text><text x="0" y="154" font-size="11">${Math.round(lo)}</text><text x="35" y="174" font-size="12">0%</text><text x="175" y="174" font-size="12">30%</text><text x="310" y="174" font-size="12">60%</text>`;
}
for(const key of ['cash','other','debtOther'])$(key).addEventListener('input',e=>{state[key]=e.target.value===''?NaN:Number(e.target.value);mark();render();});$('pools').addEventListener('input',e=>{const {i,key}=e.target.dataset;if(key){state.pools[+i][key]=['name','type'].includes(key)?e.target.value:e.target.value===''?NaN:Number(e.target.value);mark();render();}});$('pools').addEventListener('click',e=>{if(e.target.dataset.remove!==undefined){state.pools.splice(+e.target.dataset.remove,1);mark();inputs();}});$('add').onclick=()=>{state.pools.push({name:'新帳戶',type:'融資',value:0,fixed:0,debt:0,trigger:130,target:166});mark();inputs();};$('drop').oninput=render;$('demo').onclick=()=>{family=JSON.parse(JSON.stringify(familyDemo));active=0;state=family[0].data;mode='示範';$('mode').textContent='目前為示範數據，不代表客戶真實部位。所有金額單位：萬元。';inputs();};$('clear').onclick=()=>{family=[{name:'客戶',data:{cash:0,other:0,debtOther:0,pools:[]}}];active=0;state=family[0].data;mark();inputs();};$('export').onclick=()=>{try{family.forEach(m=>RiskEngine.validate(m.data));const url=URL.createObjectURL(new Blob([JSON.stringify({version:2,date:$('date').value,mode,members:family},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='client-risk.json';a.click();URL.revokeObjectURL(url);}catch(e){$('error').textContent=e.message;}};$('import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1e6)throw Error('檔案需小於1MB');const data=JSON.parse(await file.text());let imported;if(data.version===2){if(!Array.isArray(data.members)||!data.members.length||data.members.length>30)throw Error('成員需介於1至30位');imported=data.members;imported.forEach(m=>{if(typeof m.name!=='string')throw Error('成員名稱不正確');RiskEngine.validate(m.data);});}else{RiskEngine.validate(data);imported=[{name:'客戶',data:{cash:data.cash,other:data.other,debtOther:data.debtOther,pools:data.pools}}];}family=imported;active=0;state=family[0].data;if(/^\d{4}-\d{2}-\d{2}$/.test(data.date))$('date').value=data.date;mark();inputs();}catch(e){$('error').textContent='匯入失敗：'+e.message;}e.target.value='';};
$('member').onchange=e=>{family[active].data=state;active=Number(e.target.value);state=family[active].data;inputs();};
$('memberName').oninput=e=>{family[active].name=e.target.value;const opt=$('member').options[active];opt.textContent=e.target.value||'未命名成員';mark();render();};
$('addMember').onclick=()=>{if(family.length>=30){$('error').textContent='最多30位成員';return;}family[active].data=state;family.push({name:'新成員 '+(family.length+1),data:{cash:0,other:0,debtOther:0,pools:[]}});active=family.length-1;state=family[active].data;mark();inputs();};
$('removeMember').onclick=()=>{if(family.length===1){$('error').textContent='至少保留一位成員；可使用清空移除數據';return;}if(!confirm('刪除「'+(family[active].name||'未命名成員')+'」與其所有帳戶？'))return;family.splice(active,1);active=Math.min(active,family.length-1);state=family[active].data;mark();inputs();};
inputs();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_leverage_risk',description:'Read current independently calculated margin and pledge risks at a stock decline percentage.',inputSchema:{type:'object',properties:{declinePercent:{type:'number',minimum:0,maximum:60}},required:['declinePercent'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(typeof input?.declinePercent!=='number'||!Number.isFinite(input.declinePercent)||input.declinePercent<0||input.declinePercent>60)throw Error('跌幅需介於0至60');RiskEngine.validate(state);return RiskEngine.family(family,input.declinePercent/100);}})).catch(()=>{});}catch{}}

function renderOverview(drop){
const total=RiskEngine.family(family,drop),rows=total.members;
const head=`<tr><th>成員／帳戶</th><th>股票市值</th><th>借款</th><th>淨資產</th><th>目前維持率</th><th>追繳距離</th><th>跌 ${pct(drop*100)} 後維持率</th><th>需還本金</th><th>現金缺口</th></tr>`;
const body=rows.map((m,i)=>{const now=RiskEngine.calculate(family[i].data),stress=m.result;const detail=now.pools.map((p,j)=>{const q=stress.pools[j];return `<tr class="${q.breach?'danger':''}"><td class="indent">${esc(p.name)}（${esc(p.type)}）</td><td>${fmt(p.value)}</td><td>${fmt(p.debt)}</td><td>—</td><td>${p.ratio===null?'無借款':pct(p.ratio)}</td><td>${p.debt===0?'—':p.value>0?pct(Math.max(0,p.buffer*100)):p.breach?'0%':'無股票觸發'}</td><td>${q.ratio===null?'無借款':pct(q.ratio)}</td><td>${q.breach?fmt(q.repay):'0'}</td><td>依成員資金</td></tr>`;}).join('');return `<tr class="memberrow"><td>${esc(m.name||'未命名成員')}${i===active?' · 編輯中':''}</td><td>${fmt(now.stock)}</td><td>${fmt(now.debt)}</td><td>${fmt(now.equity)}</td><td colspan="3">${stress.breached} 個帳戶低於情境門檻</td><td>${fmt(stress.repay)}</td><td>${fmt(stress.cashGap)}</td></tr>${detail}`;}).join('');
$('overview').innerHTML=`<thead>${head}</thead><tbody>${body}<tr class="totalrow"><td>家庭合計（${rows.length} 位成員）</td><td>${fmt(RiskEngine.family(family,0).stock)}</td><td>${fmt(total.debt)}</td><td>${fmt(RiskEngine.family(family,0).equity)}</td><td colspan="3">${total.breached} 個帳戶低於情境門檻</td><td>${fmt(total.repay)}</td><td>${fmt(total.cashGap)}</td></tr></tbody>`;
const max=Math.max(1,...rows.flatMap(m=>[RiskEngine.calculate(family[rows.indexOf(m)].data).equity,m.result.equity]).map(Math.abs));
$('comparison').innerHTML=rows.map((m,i)=>{const before=RiskEngine.calculate(family[i].data).equity,after=m.result.equity;return `<div class="compareRow"><strong>${esc(m.name||'未命名成員')}</strong><div><div class="barlabel">目前淨資產 ${fmt(before)} 萬</div><div class="bar" style="width:${Math.abs(before)/max*100}%;background:${before<0?'#b93d3d':'#1c4469'}"></div><div class="barlabel">跌 ${pct(drop*100)} 後 ${fmt(after)} 萬${after<0?'（負值）':''}</div><div class="bar" style="width:${Math.abs(after)/max*100}%;background:${after<0?'#b93d3d':'#139c92'}"></div></div></div>`;}).join('');
$('familyStats').textContent=`股票合計 ${fmt(RiskEngine.family(family,0).stock)} 萬 · 借款合計 ${fmt(total.debt)} 萬 · 情境後淨資產 ${fmt(total.equity)} 萬 · 個別成員現金缺口合計 ${fmt(total.cashGap)} 萬`;
}
